921	    <script>
922	      // ============ Quests: calendar + Daily/Weekly/Monthly checklists ============
923	      // The calendar is a GitHub-style heat-map. Each day's GREEN INTENSITY (lvl1-4)
924	      // reflects how many of that day's dailies got done. Today's cell updates LIVE
925	      // as you click dailies. Checks persist (localStorage); dailies reset each new
926	      // day. Sample history seeds past days so the skeleton looks alive.
927	      (function () {
928	        const now = new Date();
929	        const year = now.getFullYear();
930	        const month = now.getMonth();          // 0-indexed
931	        const todayN = now.getDate();
932	        const todayKey = year + "-" + month + "-" + todayN;
933	        const levelsKey = "lodestar.levels." + year + "-" + month;
934	
935	        // ----- persistence helpers -----
936	        function load(key, fallback) {
937	          try { const v = JSON.parse(localStorage.getItem(key)); return v == null ? fallback : v; }
938	          catch (e) { return fallback; }
939	        }
940	        function save(key, val) { try { localStorage.setItem(key, JSON.stringify(val)); } catch (e) {} }
941	        // keep only well-formed { label, checked, created } items (migrates old
942	        // data — tasks saved before timestamps existed get stamped "now").
943	        function sanitize(arr) {
944	          if (!Array.isArray(arr)) return [];
945	          return arr.filter((x) => x && typeof x.label === "string")
946	                    .map((x) => ({
947	                      label: x.label,
948	                      checked: !!x.checked,
949	                      created: (typeof x.created === "number") ? x.created : Date.now(),
950	                    }));
951	        }
952	
953	        // ----- checklists: each item is { label, checked }. Lists GROW as you
954	        // add routines (the ADHD way — one at a time). Daily seeds your real
955	        // seven; weekly/monthly start empty until you add to them. -----
956	        const DEFAULT_DAILY = ["Meds","Laundry","Cleanup","Cat breakfast","Cat litter","Cat water","Cat dinner"];
957	
958	        // daily keeps its labels but resets the CHECKS each new day
959	        let daily = load("lodestar.daily", null);
960	        if (!daily || !Array.isArray(daily.items)) {
961	          daily = { date: todayKey, items: DEFAULT_DAILY.map((l) => ({ label: l, checked: false, created: Date.now() })) };
962	        } else if (daily.date !== todayKey) {
963	          daily.date = todayKey;
964	          daily.items.forEach((it) => (it.checked = false));   // new day: clear the checks
965	        }
966	        daily.items = sanitize(daily.items);
967	        // a daily's "made on" date should always read today (the chore is the
968	        // same every day). Re-stamp any item carried over from a prior day —
969	        // this also heals state stuck by an earlier same-day refresh.
970	        const startOfToday = new Date(year, month, todayN).getTime();
971	        daily.items.forEach((it) => { if (!it.created || it.created < startOfToday) it.created = Date.now(); });
972	        save("lodestar.daily", daily);
973	
974	        let weekly = sanitize(load("lodestar.weekly", []));
975	        let monthly = sanitize(load("lodestar.monthly", []));
976	        let fridge = sanitize(load("lodestar.fridge", []));   // what's thawing
977	
978	        // per-day calendar levels for THIS month; seeded with sample history
979	        const SAMPLE = { 14: 4, 15: 3, 17: 2, 18: 4, 19: 1 };
980	        let levels = load(levelsKey, {});
981	
982	        // today's green level from fraction of dailies done (0 = none, 4 = all)
983	        function dailyLevel() {
984	          const items = daily.items;
985	          if (!items.length) return 0;
986	          const done = items.filter((i) => i.checked).length;
987	          if (done === 0) return 0;
988	          return Math.min(4, Math.ceil((done / items.length) * 4));
989	        }
990	
991	        // ----- build the calendar -----
992	        document.getElementById("qcalMonth").textContent =
993	          now.toLocaleString("en-US", { month: "long" }) + " " + year;
994	        const grid = document.getElementById("qcalGrid");
995	        let todayCell = null;
996	
997	        function renderCalendar() {
998	          grid.innerHTML = "";
999	          ["S","M","T","W","T","F","S"].forEach((d) => {
1000	            const c = document.createElement("div");
1001	            c.className = "dow"; c.textContent = d; grid.appendChild(c);
1002	          });
1003	          const firstDow = new Date(year, month, 1).getDay();
1004	          const dim = new Date(year, month + 1, 0).getDate();
1005	          for (let i = 0; i < firstDow; i++) {
1006	            const e = document.createElement("div"); e.className = "qd empty"; grid.appendChild(e);
1007	          }
1008	          for (let day = 1; day <= dim; day++) {
1009	            const cell = document.createElement("div");
1010	            cell.className = "qd";
1011	            let lvl = 0;
1012	            if (day === todayN) { lvl = dailyLevel(); todayCell = cell; cell.classList.add("today"); }
1013	            else if (levels[day] != null) lvl = levels[day];
1014	            else if (SAMPLE[day] != null) lvl = SAMPLE[day];
1015	            if (lvl > 0) cell.classList.add("lvl" + lvl);
1016	            cell.title = day;        // date on hover; no number shown
1017	            if (shrine[day]) cell.classList.add("starred");   // Shrine works this day
1018	            cell.addEventListener("click", () => toggleStar(day, cell));
1019	            grid.appendChild(cell);
