(() => {
  const board = document.querySelector('.board-projects');
  if (!board) return 'projects board not built yet';
  // header widths (the grid template applied to the header row)
  const head = board.querySelector('.board-head');
  const tmpl = head ? head.style.gridTemplateColumns : '(none)';
  // find the Status column cells (col-status) and report whether each is text or an <img>
  const statusCells = [...board.querySelectorAll('.col-status')].map(c => {
    const img = c.querySelector('img.sb-iconimg');
    return img ? ('IMG → ' + img.getAttribute('src')) : ('TEXT → "' + c.textContent.trim() + '"');
  });
  return { gridTemplateColumns: tmpl, statusCells };
})()

