input.query:
-- Reconsolidation by supersession: a recalled memory updated by present context
-- is re-filed as a NEW row; the original is kept forever and marked superseded.
alter table hippocampus add column if not exists superseded_by integer;
alter table hippocampus add column if not exists superseded_at timestamptz;
alter table hippocampus add column if not exists reconsolidated_from integer;

comment on column hippocampus.superseded_by is 'Reconsolidation: if set, THIS row is a retired/old version, superseded by the memory with this id. Kept for audit/rollback; excluded from all surfacing paths. Null = live/current.';
comment on column hippocampus.superseded_at is 'When this row was superseded (reconsolidated away). Null = never.';
comment on column hippocampus.reconsolidated_from is 'Inverse of superseded_by: if set, THIS row is an updated version re-filed from the memory with this id. Lets the version chain be walked both directions.';

create index if not exists hippocampus_superseded_by_idx on hippocampus (superseded_by);

-- Surfacing exclusion at the source: superseded ghosts never come back as semantic
-- neighbours. Also keeps a reconsolidated memory from matching its own retired
-- predecessor as a near-duplicate.
create or replace function public.semantic_neighbors(query_embedding vector, match_corridor text, exclude_id integer, match_count integer default 5)
returns table(id integer, content text, weight integer, similarity double precision)
language sql stable as $function$
  select id, content, weight, 1 - (embedding <=> query_embedding) as similarity
  from hippocampus
  where corridor = match_corridor
    and id != exclude_id
    and embedding is not null
    and superseded_by is null
  order by embedding <=> query_embedding
  limit match_count;
$function$;

